    const bytes = encoder.encode(source);
    expect(bytes[65535]! & 0xc0).toBe(0x80);
    expect(() => new TextDecoder('utf-8', { fatal: true }).decode(bytes.slice(0, 65536))).toThrow();
    const table = auto(source, true);
