it('enforces standard alphabet, encode-only modes and the 5 MiB image limit', async () => {
    await expect(run(png, 'image/png', { urlSafe: true })).rejects.toThrow('URL-safe');
    await expect(run(png, 'image/png', { mode: 'decode' })).rejects.toThrow('encode');
    await expect(run(png, 'image/png', { encodeOutput: 'unknown' })).rejects.toThrow('output');
    await expect(run(new Uint8Array(5 * 1024 * 1024 + 1), '')).rejects.toThrow('5 MiB');
  })

it('keeps raw arbitrary-file encoding unchanged and allows larger downloadable output', async () => {
    expect(
      await (await run(new Uint8Array([0, 255]), 'text/plain', { encodeOutput: 'raw' })).text(),
    ).toBe('AP8=');
    const large = new Uint8Array(200000);
    large.set(png);
    expect((await run(large)).size).toBe(22 + Math.ceil(large.length / 3) * 4);
  })

it('respects cancellation without emitting done', async () => {
    const controller = new AbortController();
    controller.abort();
    const stages: string[] = [];
    await expect(
      base64.run(
        [new File([png], 'image.png', { type: 'image/png' })],
        { mode: 'encode', encodeOutput: 'data-url' },
        { ...ctx(), signal: controller.signal, onProgress: (p) => stages.push(p.stage) },
      ),
    ).rejects.toThrow('Aborted');
    expect(stages).not.toContain('done');
  })

it('has id regex-tester', () => {
    expect(regexTester.id).toBe('regex-tester');
  })

it('is in the inspect category', () => {
    expect(regexTester.category).toBe('inspect');
  })

it('accepts text/plain, min 1, max 1', () => {
    expect(regexTester.input.accept).toContain('text/plain');
    expect(regexTester.input.min).toBe(1);
    expect(regexTester.input.max).toBe(1);
  })

it('finds matches in text', async () => {
    const result = await test('hello world hello', 'hello', 'g');
    expect(result.valid).toBe(true);
    expect(result.matchCount).toBe(2);
    expect(result.matches.length).toBe(2);
    expect(result.matches[0]!.match).toBe('hello');
  })

it('returns match positions (index)', async () => {
    const result = await test('abc def abc', 'abc', 'g');
    expect(result.matches[0]!.index).toBe(0);
    expect(result.matches[1]!.index).toBe(8);
  })

it('handles named groups', async () => {
    const result = await test('2026-04-15', '(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})', 'g');
    expect(result.valid).toBe(true);
    expect(result.matchCount).toBe(1);
    expect(result.matches[0]!.groups).toBeDefined();
    expect(result.matches[0]!.groups!['year']).toBe('2026');
    expect(result.matches[0]!.groups!['month']).toBe('04');
    expect(result.matches[0]!.groups!['day']).toBe('15');
  })

it('returns valid:false for invalid regex syntax', async () => {
    const result = await test('some text', '[invalid(', 'g');
    expect(result.valid).toBe(false);
    expect(result.error).toBeTruthy();
    expect(result.matchCount).toBe(0);
  })

it('handles no matches', async () => {
    const result = await test('hello world', 'xyz', 'g');
    expect(result.valid).toBe(true);
    expect(result.matchCount).toBe(0);
    expect(result.matches.length).toBe(0);
  })

it('output MIME type is application/json', async () => {
    const file = new File(['test'], 'input.txt', { type: 'text/plain' });
    const [out] = (await regexTester.run([file], { pattern: 'test' }, makeCtx())) as Blob[];
    expect(out!.type).toBe('application/json');
  })

it('handles non-global flags (single match)', async () => {
    const result = await test('aaa', 'a', '');
    expect(result.valid).toBe(true);
    expect(result.matchCount).toBe(1);
  })

it('truncates at 10000 matches on large input and sets truncated=true', async () => {
    const bigText = 'a'.repeat(20 * 1024); // 20 KB — more than 10000 chars
    const result = await test(bigText, '.', 'g');
    expect(result.valid).toBe(true);
    expect(result.truncated).toBe(true);
    expect(result.matches.length).toBe(10000);
  })

it('has sizeLimit of 1 MB on input spec', () => {
    expect(regexTester.input.sizeLimit).toBe(1 * 1024 * 1024);
  })

it('rejects a catastrophic nested-quantifier pattern quickly instead of hanging', async () => {
    // (a+)+$ against a long non-matching input is the classic ReDoS shape.
    // Without the static guard this would backtrack exponentially and hang
    // the event loop; with it, run() returns an error verdict in ms.
    const start = Date.now();
    const result = await test('a'.repeat(40) + '!', '(a+)+$', 'g');
    const elapsed = Date.now() - start;
    expect(result.valid).toBe(false);
    expect(result.error).toMatch(/ReDoS|catastrophic|nested/i);
    expect(result.matchCount).toBe(0);
    expect(elapsed).toBeLessThan(1000);
  })

it('rejects an over-long pattern', async () => {
    const result = await test('hello', 'a'.repeat(1001), 'g');
    expect(result.valid).toBe(false);
    expect(result.error).toMatch(/too long/i);
  })

it('still accepts a benign single-quantifier pattern', async () => {
    const result = await test('aaa bbb', 'a+', 'g');
    expect(result.valid).toBe(true);
    expect(result.matchCount).toBe(1);
  })

it.each(['--255', '-+255'])('rejects malformed double signs %s', async (text) => {
    await expect(run(text, { inputBase: 10 })).rejects.toThrow('integer sign');
  })

it.each([
    ['-0xFF', 'auto', '-255'],
    ['-0b1010', 'auto', '-10'],
    ['-0o10', 'auto', '-8'],
    ['-FF', 16, '-255'],
    ['-1010', 2, '-10'],
    ['-10', 8, '-8'],
    ['-255', 10, '-255'],
  ] as const)(
    'converts signed %s without passing a signed radix prefix to BigInt',
    async (value, inputBase, decimal) => {
      const result = JSON.parse(await (await run(value, { inputBase })).text()) as NumberBaseResult;
      expect(result.decimal).toBe(decimal);
      expect(result.binary.startsWith('-')).toBe(true);
      expect(result.hexadecimal.startsWith('-')).toBe(true);
    },
  )

it('retains the unprefixed autodetection contract', async () => {
    const decimal = async (text: string) =>
      (JSON.parse(await (await run(text)).text()) as NumberBaseResult).decimal;
    expect(await decimal('10')).toBe('2');
    expect(await decimal('77')).toBe('63');
    expect(await decimal('FF')).toBe('255');
    expect(await decimal('99')).toBe('99');
  })

it.each([
    ['binary', '11000011 10101001'],
    ['hex', 'c3 a9'],
    ['decimal', '195 169'],
  ] as const)('encodes and decodes known Unicode bytes in %s', async (byteFormat, bytes) => {
    const encoded = await run('é', { conversionKind: 'utf8-bytes', byteFormat });
    expect(encoded.type).toBe('text/plain');
    expect(await encoded.text()).toBe(bytes);
    expect(
      await (
        await run(bytes, { conversionKind: 'utf8-bytes', direction: 'decode', byteFormat })
      ).text(),
    ).toBe('é');
  })

assertions.assertion:
expect(
      await (
        await run(bytes, { conversionKind: 'utf8-bytes', direction: 'decode', byteFormat })
      ).text(),
