it('preserves whitespace, BOM and empty strings', async () => {
    expect(convertUtf8Bytes(' ', 'encode', 'binary')).toBe('00100000');
    expect(convertUtf8Bytes(' ', 'encode', 'hex')).toBe('20');
    expect(convertUtf8Bytes(' ', 'encode', 'decimal')).toBe('32');
    expect(convertUtf8Bytes('\ufeff\n', 'encode', 'hex')).toBe('ef bb bf 0a');
    expect(convertUtf8Bytes('ef bb bf 0a', 'decode', 'hex')).toBe('\ufeff\n');
    expect(convertUtf8Bytes('  C3  A9  ', 'decode', 'hex')).toBe('é');
    expect(await (await run('', { conversionKind: 'utf8-bytes' })).text()).toBe('');
    expect(convertUtf8Bytes('', 'decode', 'binary')).toBe('');
  })

it.each(['\ud800', '\udc00', 'a\ud800b'])(
    'rejects lone surrogates in original strings',
    (value) => {
      expect(() => convertUtf8Bytes(value, 'encode', 'hex')).toThrow('Unpaired UTF-16 surrogate');
    },
  )

it('retains exact numeric JSON formatting and truthful mode MIME', async () => {
    const output = await run('255', { inputBase: 10 });
    expect(output.type).toBe('application/json');
    expect(await output.text()).toBe(
      '{\n  "decimal": "255",\n  "binary": "11111111",\n  "octal": "377",\n  "hexadecimal": "FF",\n  "binaryPadded": "11111111",\n  "hexPadded": "FF"\n}',
    );
    expect(numberBaseConverter.output.mime).toBe('*/*');
    expect(numberBaseConverter.__testFixtures?.expectedOutputMime).toEqual([
      'application/json',
      'text/plain',
    ]);
    expect(Object.keys(numberBaseConverter.paramSchema!)[0]).toBe('conversionKind');
  })

it('rejects file size, malformed UTF-8 input, invalid parameters and cancellation', async () => {
    await expect(
      run('a'.repeat(1024 * 1024 + 1), { conversionKind: 'utf8-bytes' }),
    ).rejects.toThrow('1 MiB');
    await expect(
      numberBaseConverter.run(
        [new File([new Uint8Array([0xc3])], 'invalid.txt')],
        { conversionKind: 'utf8-bytes' },
        ctx(),
      ),
    ).rejects.toThrow('valid UTF-8');
    expect(() => convertUtf8Bytes('x', 'other' as 'encode', 'hex')).toThrow('direction');
    const controller = new AbortController();
    controller.abort();
    await expect(
      numberBaseConverter.run(
        [new File(['x'], 'x.txt')],
        {},
        { ...ctx(), signal: controller.signal },
      ),
    ).rejects.toThrow('Aborted');
  })

it('has id number-base-converter', () => {
    expect(numberBaseConverter.id).toBe('number-base-converter');
  })

it('is in the dev category', () => {
    expect(numberBaseConverter.category).toBe('dev');
  })

it('declares mode-specific output types through a MIME pattern', () => {
    expect(numberBaseConverter.output.mime).toBe('*/*');
  })

it('converts decimal 255 to all bases', async () => {
    const result = await run('255', 10);
    expect(result.decimal).toBe('255');
    expect(result.binary).toBe('11111111');
    expect(result.octal).toBe('377');
    expect(result.hexadecimal).toBe('FF');
  })

it('converts hex FF auto-detected', async () => {
    const result = await run('FF', 'auto');
    expect(result.decimal).toBe('255');
  })

it('converts binary 1010 to decimal 10', async () => {
    const result = await run('1010', 2);
    expect(result.decimal).toBe('10');
  })

it('handles 0x prefix for hex', async () => {
    const result = await run('0xFF', 'auto');
    expect(result.decimal).toBe('255');
  })

it('pads binary to 8-bit boundary', async () => {
    const result = await run('255', 10);
    expect(result.binaryPadded.length % 8).toBe(0);
  })

it('pads hex to 2-char boundary', async () => {
    const result = await run('255', 10);
    expect(result.hexPadded.length % 2).toBe(0);
  })

it('handles large numbers via BigInt', async () => {
    const result = await run('9999999999999999999', 10);
    expect(result.decimal).toBe('9999999999999999999');
  })

it('throws on empty input', async () => {
    const file = new File([''], 'input.txt', { type: 'text/plain' });
    await expect(numberBaseConverter.run([file], {}, makeCtx())).rejects.toThrow('empty');
  })

it('rejects more than one integer sign before magnitude parsing', async () => {
  const context = {
    signal: new AbortController().signal,
    cache: new Map(),
    executionId: 'sign-test',
    onProgress() {},
  };
  for (const text of ['-+255', '--255', '+-255', '++255']) {
    await expect(
      numberBaseConverter.run(
        [new File([text], 'number.txt', { type: 'text/plain' })],
        { inputBase: 10 },
        context,
      ),
    ).rejects.toThrow();
  }
})

it('treats 0b10 as hexadecimal digits when base 16 is explicitly selected', async () => {
    // B*16^2 + 1*16 = 11*256 + 16 = 2832, not binary 2 or hex 16.
    expect(await convert('0b10', { inputBase: 16 })).toEqual({
      decimal: '2832',
      binary: '101100010000',
      octal: '5420',
      hexadecimal: 'B10',
      binaryPadded: '0000101100010000',
      hexPadded: '0B10',
    });
  })

it('applies the minus after explicit hexadecimal magnitude parsing', async () => {
    expect(await convert('-0b10', { inputBase: 16 })).toEqual({
      decimal: '-2832',
      binary: '-101100010000',
      octal: '-5420',
      hexadecimal: '-B10',
      binaryPadded: '-0000101100010000',
      hexPadded: '-0B10',
    });
  })

it.each([
    [10, '0b10'],
    [10, '0x10'],
    [10, '0o10'],
    [8, '0x10'],
    [8, '0b10'],
    [2, '0o10'],
    [2, '0x10'],
  ] as const)('rejects mismatched prefix %s / %s', async (inputBase, text) => {
    await expect(convert(text, { inputBase })).rejects.toThrow(/invalid.*base|digit/i);
    await expect(convert(`-${text}`, { inputBase })).rejects.toThrow(/invalid.*base|digit/i);
  })

it.each([
    [2, '0b1010', '10'],
    [2, '0B1010', '10'],
    [8, '0o17', '15'],
    [8, '0O17', '15'],
    [16, '0xFF', '255'],
    [16, '0XFF', '255'],
  ] as const)('retains matching prefixes for base %s / %s', async (inputBase, text, expected) => {
    expect((await convert(text, { inputBase })).decimal).toBe(expected);
    expect((await convert(`-${text}`, { inputBase })).decimal).toBe(`-${expected}`);
  })

it.each(['- 255', '-\t255', '-\n255', '+ 255', '+\t255', '+\n255'])(
    'rejects internal sign whitespace %j',
    async (text) => {
      await expect(convert(text, { inputBase: 10 })).rejects.toThrow(/whitespace|invalid|sign/i);
    },
  )

it('rejects internal sign whitespace in auto mode too', async () => {
    await expect(convert('- 10', { inputBase: 'auto' })).rejects.toThrow(
      /whitespace|invalid|sign/i,
    );
  })

it('reports unsupported base distinctly for direct callers', async () => {
    const unsupported = { inputBase: 4 } as unknown as NumberBaseConverterParams;
    await expect(convert('10', unsupported)).rejects.toThrow(/unsupported base/i);
  })

it('preserves auto plus-decimal and unprefixed binary heuristics', async () => {
    expect((await convert('+10', { inputBase: 'auto' })).decimal).toBe('10');
    expect((await convert('10', { inputBase: 'auto' })).decimal).toBe('2');
    expect((await convert('10')).decimal).toBe('2');
    expect((await convert('-10', { inputBase: 'auto' })).decimal).toBe('-2');
    expect((await convert('-0xFF', { inputBase: 'auto' })).decimal).toBe('-255');
    expect((await convert('-0b1010', { inputBase: 'auto' })).decimal).toBe('-10');
  })

it('retains exterior trimming, negative output fields and sign-free padding', async () => {
    expect(await convert(' \t-255\n', { inputBase: 10 })).toEqual({
      decimal: '-255',
      binary: '-11111111',
      octal: '-377',
      hexadecimal: '-FF',
      binaryPadded: '-11111111',
      hexPadded: '-FF',
    });
  })

