    ]);
    expect(queryJsonPath({ "a'b\\c": 4 }, "$['a\\'b\\\\c']")).toEqual([
      { path: '$["a\'b\\\\c"]', value: 4 },
    ]);
    expect(queryJsonPath({ 'a.b': 5, nested: { 'a.b': 6 } }, '$..["a.b"]')).toEqual([
