    { module: false },
    { module: bool('ES module') },
    async (text, params, ctx) => {
      abort(ctx);
      const { minify } = await import('terser');
      const result = await minify(text, {
        module: params.module === true,
        compress: false,
        mangle: false,
        keep_fnames: true,
        keep_classnames: true,
        format: { comments: false },
      });
      abort(ctx);
      return result.code ?? '';
    },
  )

