urlEncoder: ToolModule<UrlEncoderParams> = {
  id: 'url-encoder',
  slug: 'url-encoder',
  name: 'URL Encoder',
  description: 'Encode or decode URL components and full URLs.',
  category: 'convert',
  keywords: ['url', 'encode', 'decode', 'percent', 'uri', 'query', 'string'],

  input: {
    accept: ['text/plain'],
    min: 1,
    max: 1,
    sizeLimit: 10 * 1024 * 1024,
  },
  output: {
    mime: 'text/plain',
    multiple: false,
  },

  interactive: false,
  batchable: false,
  cost: 'free',
  memoryEstimate: 'low',

  chainSuggestions: ['slug', 'text-escape', 'case-converter'],
  defaults: { mode: 'encode', scope: 'component' },

  paramSchema: {
    mode: {
      type: 'enum',
      label: 'mode',
      options: [
        { value: 'encode', label: 'encode' },
        { value: 'decode', label: 'decode' },
      ],
    },
    scope: {
      type: 'enum',
      label: 'scope',
      help: '"component" escapes everything (use for query values). "full URL" preserves : / ? & # — use when encoding an entire URL.',
      options: [
        { value: 'component', label: 'component (encodeURIComponent)' },
        { value: 'full', label: 'full URL (encodeURI)' },
      ],
    },
  },

  async run(inputs: File[], params: UrlEncoderParams, ctx: ToolRunContext): Promise<Blob[]> {
    ctx.onProgress({ stage: 'processing', percent: 0, message: 'Processing URL' });

    const text = await inputs[0]!.text();
    const scope = params.scope ?? 'component';
    let result: string;

    if (params.mode === 'encode') {
      result = scope === 'component' ? encodeURIComponent(text) : encodeURI(text);
    } else {
      try {
        result = scope === 'component' ? decodeURIComponent(text) : decodeURI(text);
      } catch (e) {
        throw new Error(`Invalid percent-encoded sequence: ${(e as Error).message}`);
      }
    }

    ctx.onProgress({ stage: 'done', percent: 100, message: 'Done' });
    return [new Blob([result], { type: 'text/plain' })];
  },

