      if (inputs.length) throw new Error('This generator does not accept files.');
      const result = generate(validateUtilityParams(defaults, schema, params));
      textBudget(result, 20 * MiB);
      abort(ctx);
      ctx.onProgress({ stage: 'done', percent: 100 });
